  import express from "express";
  import { CreateProjectUseCase } from "../application/CreateProjectUseCase";
  import { CreateTaskUseCase } from "../application/CreateTaskUseCase";
  import { CreateUserUseCase } from "../application/CreateUserUseCase";
  import { ListProjectTasksUseCase } from "../application/ListProjectTasksUseCase";
  import { MarkTaskDoneUseCase } from "../application/MarkTaskDoneUseCase";
  import { InMemoryProjectRepository, InMemoryTaskRepository, InMemoryUserRepository } from "./InMemoryRepositories";
  import { TaskController } from "./TaskController";

  const users = new InMemoryUserRepository();
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();
  const controller = new TaskController({
    createUser: new CreateUserUseCase(users),
    createProject: new CreateProjectUseCase(projects),
    createTask: new CreateTaskUseCase(projects, users, tasks),
    listTasks: new ListProjectTasksUseCase(projects, tasks),
    markDone: new MarkTaskDoneUseCase(tasks),
  });

  const app = express();
  app.use(express.json());
  app.use(controller.router());

  const port = Number(process.env.PORT ?? 3000);
  app.listen(port, () => console.log(`Task API listening on port ${port}`));

